mapper.sql:
WHERE d.deleted = 0

    AND (d.name LIKE CONCAT('%', #{query.keyword}, '%')
         OR d.description LIKE CONCAT('%', #{query.keyword}, '%')
         OR s.name LIKE CONCAT('%', #{query.keyword}, '%'))


    AND d.stall_id = #{query.stallId}


    AND s.area = #{query.area}


    AND s.floor = #{query.floor}


    AND d.category = #{query.category}


    AND d.price >= #{query.minPrice}


    AND d.price <= #{query.maxPrice}

mapper.select:
SELECT
,


        EXISTS(SELECT 1 FROM dish_favorite f WHERE f.dish_id = d.id AND f.user_id = #{userId}) AS favorited


        0 AS favorited


FROM dish d
LEFT JOIN canteen_stall s ON d.stall_id = s.id AND s.deleted = 0
LEFT JOIN dish_review r ON r.dish_id = d.id AND r.deleted = 0 AND r.status = 1


    AND d.status = 1


    AND d.status = #{query.status}


    AND d.audit_status = #{query.auditStatus}



    HAVING avg_rating >= #{query.minRating}

ORDER BY ${orderSql}

SELECT d.id, d.stall_id, d.name, d.price, d.category, d.image, d.description, d.status, d.audit_status, d.audit_remark, d.audit_by, d.audit_time, d.create_time, d.update_time, s.name AS stall_name FROM dish d LEFT JOIN canteen_stall s ON s.id = d.stall_id AND s.deleted = 0 WHERE d.deleted = 0
AND d.audit_status = #{status}
ORDER BY d.update_time DESC, d.id DESC
